def detect_opp_archetype(opp_ids: set) -> str:
    """Грубый детектор БЕЗ sticky-состояния -- каждый вызов решает только по видимым в ЭТОМ
    снимке id (в отличие от main.py's _detect_matchup_raw, который держит module-level sticky
    global между вызовами одной партии). Первое совпадение по ARCHETYPE_ORDER побеждает;
    ничего не подошло -> "generic". Never-throw: вызывающая сторона (value_features) уже
    оборачивает всё в try/except, здесь дополнительной защиты не требуется -- чистая
    set-арифметика без обращения к полям с непредсказуемой формой.
    """
    for name in ARCHETYPE_ORDER:
        if opp_ids & ARCHETYPE_SIGNATURES[name]:
            return name
    return "generic"


ARCHETYPE_LABELS: tuple = ARCHETYPE_ORDER + ("generic",)


def _mon(lst):
    if isinstance(lst, list) and lst and isinstance(lst[0], dict):
        return lst[0]
    return None


def _card_id_counts(cards) -> dict:
    counts: dict = {}
    if isinstance(cards, list):
        for c in cards:
            if isinstance(c, dict) and c.get("id") is not None:
                cid = int(c["id"])
                counts[cid] = counts.get(cid, 0) + 1
    return counts


def _bucket_counts(cards) -> tuple:
    """(n_pokemon, n_energy, n_supporter, n_other_trainer) по CLASS_BY_ID -- работает для
    ЛЮБОЙ карты в игре (не только своей колоды), см. докстринг модуля про CLASS_BY_ID."""
    n_pk = n_en = n_sup = n_other = 0
    if isinstance(cards, list):
        for c in cards:
            if not isinstance(c, dict) or c.get("id") is None:
                continue
            cls = CLASS_BY_ID.get(int(c["id"]))
            if cls == 0:
                n_pk += 1
            elif cls == 4:
                n_en += 1
            elif cls == 2:
                n_sup += 1
            elif cls in (1, 3, 5):
                n_other += 1
    return float(n_pk), float(n_en), float(n_sup), float(n_other)


def _discard_ex_count(cards) -> float:
    if not isinstance(cards, list):
        return 0.0
    n = 0
    for c in cards:
        if isinstance(c, dict) and c.get("id") is not None:
            if _bcf.prize_value(int(c["id"])) >= 2:
                n += 1
    return float(n)


def _status(player: dict, key: str) -> float:
    return 1.0 if (isinstance(player, dict) and player.get(key)) else 0.0


def _board_stats(player: dict, hand_visible: bool) -> dict:
    """Полный борд ОДНОЙ стороны -- используется дважды на вызов (own/opp), см.
    value_features. `hand_visible` гейтит hand-breakdown фичи (см. докстринг модуля про
    видимость -- opponent hand в этих снимках всегда None/только handCount)."""
    player = player if isinstance(player, dict) else {}
    active_mon = _mon(player.get("active"))
    bench = [m for m in (player.get("bench") or []) if isinstance(m, dict)]
    bench_n = len(bench)
    bench_hp_sum = 0.0
    bench_maxhp_sum = 0.0
    bench_energy_sum = 0.0
    bench_frac_terms = []
    for m in bench:
        hp, mx = m.get("hp"), m.get("maxHp")
        if isinstance(hp, (int, float)):
            bench_hp_sum += float(hp)
        if isinstance(mx, (int, float)):
            bench_maxhp_sum += float(mx)
        if isinstance(hp, (int, float)) and isinstance(mx, (int, float)) and mx:
            bench_frac_terms.append(hp / mx)
        bench_energy_sum += float(len(m.get("energies") or []))
    bench_avg_hp_frac = (sum(bench_frac_terms) / len(bench_frac_terms)) if bench_frac_terms else SENTINEL

    if active_mon is not None:
        hp, mx = active_mon.get("hp"), active_mon.get("maxHp")
        hp = hp if isinstance(hp, (int, float)) else None
        mx = mx if isinstance(mx, (int, float)) else None
        a_id = active_mon.get("id")
        a_id = int(a_id) if a_id is not None else None
        a_hp = float(hp) if hp is not None else SENTINEL
        a_mx = float(mx) if mx is not None else SENTINEL
        a_dmg = float(mx - hp) if (hp is not None and mx is not None) else SENTINEL
        a_frac = float(hp / mx) if (hp is not None and mx not in (None, 0)) else SENTINEL
        a_en = float(len(active_mon.get("energies") or []))
        a_tools = float(len(active_mon.get("tools") or []))
        a_stage = float(STAGE_BY_ID.get(a_id, -1)) if a_id is not None else SENTINEL
        a_prize = float(_bcf.prize_value(a_id)) if a_id is not None else SENTINEL
        a_present = 1.0
    else:
        a_id, a_hp, a_mx, a_dmg, a_frac = None, SENTINEL, SENTINEL, SENTINEL, SENTINEL
        a_en, a_tools, a_stage, a_prize, a_present = 0.0, 0.0, SENTINEL, SENTINEL, 0.0

    hand = player.get("hand")
    if hand_visible and isinstance(hand, list):
        h_pk, h_en, h_sup, h_other = _bucket_counts(hand)
    else:
        h_pk, h_en, h_sup, h_other = SENTINEL, SENTINEL, SENTINEL, SENTINEL

    discard = player.get("discard") or []
    d_pk, d_en, d_sup, d_other = _bucket_counts(discard)
    d_ex = _discard_ex_count(discard)

    return {
        "deck_count": float(player.get("deckCount")) if player.get("deckCount") is not None else SENTINEL,
        "hand_count": float(player.get("handCount")) if player.get("handCount") is not None else SENTINEL,
        "prize_left": float(len(player.get("prize") or [])),
        "bench_n": float(bench_n),
        "discard_n": float(len(discard)),
        "active_present": a_present, "active_id": a_id, "active_hp": a_hp, "active_maxhp": a_mx,
        "active_damage": a_dmg, "active_hp_frac": a_frac, "active_n_energies": a_en,
        "active_n_tools": a_tools, "active_stage": a_stage, "active_prize_value": a_prize,
        "bench_hp_sum": float(bench_hp_sum), "bench_maxhp_sum": float(bench_maxhp_sum),
        "bench_energy_sum": float(bench_energy_sum), "bench_avg_hp_frac": bench_avg_hp_frac,
        "asleep": _status(player, "asleep"), "burned": _status(player, "burned"),
        "confused": _status(player, "confused"), "paralyzed": _status(player, "paralyzed"),
        "poisoned": _status(player, "poisoned"),
        "hand_pokemon_n": h_pk, "hand_energy_n": h_en, "hand_supporter_n": h_sup,
        "hand_other_trainer_n": h_other,
        "discard_pokemon_n": d_pk, "discard_energy_n": d_en, "discard_supporter_n": d_sup,
        "discard_other_trainer_n": d_other, "discard_ex_n": d_ex,
        "_opp_ids": ({int(m["id"]) for m in ([active_mon] if active_mon else []) + bench
                       if isinstance(m, dict) and m.get("id") is not None}),
    }

