def value_features(obs_dict: dict, me_index: int) -> list:
    """КОНТРАКТ (см. докстринг модуля): list[float] длины N_FEATURES, порядок = FEATURE_ORDER.
    Never-throw наружу НЕ гарантируется здесь по контракту (в отличие от bc_features_2b) --
    вызывающий код (offline dataset builder ИЛИ будущий leaf-eval в search_gs.py) сам решает,
    оборачивать ли в try/except; при офлайн-сборке датасета исключение на одной записи должно
    быть видно, а не тихо проглочено."""
    cur = obs_dict.get("current") or {}
    me = int(me_index)
    opp = 1 - me
    players = cur.get("players") or []
    while len(players) < 2:
        players = players + [{}]
    mine = players[me] if 0 <= me < len(players) else {}
    theirs = players[opp] if 0 <= opp < len(players) else {}

    own = _board_stats(mine, hand_visible=True)
    oppb = _board_stats(theirs, hand_visible=False)

    stadium = cur.get("stadium") or []
    stadium_card = stadium[0] if stadium and isinstance(stadium[0], dict) else None
    stadium_id = stadium_card.get("id") if stadium_card else None

    turn = cur.get("turn")
    turn_f = float(turn) if isinstance(turn, (int, float)) else SENTINEL
    first_player = cur.get("firstPlayer")
    is_first = 1.0 if first_player == me else 0.0
    if isinstance(turn, int):
        # чей ход: turn -- глобальный алтернирующий счётчик (подтверждено на живых снимках
        # корпуса -- ходы одной стороны идут через один turn_idx), первый игрок ходит на
        # чётных turn, второй -- на нечётных.
        turn_is_even = (turn % 2 == 0)
        is_my_turn = 1.0 if (turn_is_even == (first_player == me)) else 0.0
        turn_parity = float(turn % 2)
    else:
        is_my_turn = SENTINEL
        turn_parity = SENTINEL

    feats = {
        "turn": turn_f, "turn_parity": turn_parity, "is_first_player": is_first,
        "is_my_turn_heuristic": is_my_turn,
        "turn_action_count": float(cur.get("turnActionCount")) if cur.get("turnActionCount") is not None else SENTINEL,
        "stadium_id": float(stadium_id) if stadium_id is not None else SENTINEL,
    }
    for k, v in own.items():
        if k == "_opp_ids":
            continue
        feats[f"own_{k}"] = v if v is not None else SENTINEL
    for k, v in oppb.items():
        if k == "_opp_ids":
            continue
        feats[f"opp_{k}"] = v if v is not None else SENTINEL

    feats["prize_diff"] = own["prize_left"] - oppb["prize_left"]
    feats["hp_diff"] = (own["active_hp"] - oppb["active_hp"]) if (own["active_hp"] != SENTINEL and oppb["active_hp"] != SENTINEL) else SENTINEL
    feats["hp_frac_diff"] = (own["active_hp_frac"] - oppb["active_hp_frac"]) if (own["active_hp_frac"] != SENTINEL and oppb["active_hp_frac"] != SENTINEL) else SENTINEL
    feats["bench_diff"] = own["bench_n"] - oppb["bench_n"]
    feats["energy_diff"] = (own["active_n_energies"] + own["bench_energy_sum"]) - (oppb["active_n_energies"] + oppb["bench_energy_sum"])
    feats["own_deckout_risk"] = 1.0 if (own["deck_count"] != SENTINEL and own["deck_count"] <= 3) else 0.0
    feats["opp_deckout_risk"] = 1.0 if (oppb["deck_count"] != SENTINEL and oppb["deck_count"] <= 3) else 0.0

    archetype = detect_opp_archetype(oppb["_opp_ids"])
    for name in ARCHETYPE_LABELS:
        feats[f"opp_arch_{name}"] = 1.0 if name == archetype else 0.0

    return [feats.get(k, SENTINEL) for k in FEATURE_ORDER]
